<?php $page_title='Order Management'; include 'includes/header.php'; $orders=$pdo->query('SELECT o.*,u.name,u.email FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.order_date DESC')->fetchAll(); ?><section class="page-banner"><div class="container"><div class="eyebrow">Customer activity</div><h1>Orders</h1></div></section><section class="section"><div class="container"><?php if(!$orders): ?><p class="muted">No orders yet.</p><?php else: ?><table class="cart-table"><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Date</th><th>Payment</th><th>Status</th></tr></thead><tbody><?php foreach($orders as $order): ?><tr><td data-label="Order">#<?=$order['id']?></td><td data-label="Customer"><?=esc($order['name'])?><br><span class="muted"><?=esc($order['email'])?></span></td><td data-label="Total">₹<?=number_format($order['total_amount'],2)?></td><td data-label="Date"><?=date('d M Y',strtotime($order['order_date']))?></td><td data-label="Payment"><?=esc($order['payment_method'])?></td><td data-label="Status"><select class="order-status" data-order="<?=$order['id']?>"><?php foreach(['Pending','Preparing','Out for Delivery','Delivered','Cancelled'] as $status): ?><option <?=$order['order_status']===$status?'selected':''?>><?=$status?></option><?php endforeach; ?></select></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div></section><script>document.querySelectorAll('.order-status').forEach(select=>select.addEventListener('change',async()=>{const result=await (await fetch('../ajax/update_order_status.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({order_id:select.dataset.order,status:select.value})})).json();showToast(result.message,!result.success);}));</script><?php include 'includes/footer.php'; ?>